import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"荡","description":"","frontmatter":{"title":"荡","date":"2026-11-09T00:00:00.000Z","seq":21,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/荡.md","filePath":"blogs/诗经·大雅/荡.md"}'),o={name:"blogs/诗经·大雅/荡.md"};function c(l,a,n,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="荡" tabindex="-1">荡 <a class="header-anchor" href="#荡" aria-label="Permalink to &quot;荡&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">荡荡上帝，下民之辟。疾威上帝，其命多辟。</p><p class="poem-stanza">天生烝民，其命匪谌。靡不有初，鲜克有终。</p><p class="poem-stanza">文王曰咨，咨汝殷商。曾是彊御？曾是掊克？</p><p class="poem-stanza">曾是在位？曾是在服？天降滔德，女兴是力。</p><p class="poem-stanza">文王曰咨，咨女殷商。而秉义类，彊御多怼。</p><p class="poem-stanza">流言以对。寇攘式内。侯作侯祝，靡届靡究。</p><p class="poem-stanza">文王曰咨，咨女殷商。女炰烋于中国。敛怨以为德。</p><p class="poem-stanza">不明尔德，时无背无侧。尔德不明，以无陪无卿。</p><p class="poem-stanza">文王曰咨，咨女殷商。天不湎尔以酒，不义从式。</p><p class="poem-stanza">既衍尔止。靡明靡晦。式号式呼。俾昼作夜。</p><p class="poem-stanza">文王曰咨，咨女殷商。如蜩如螗，如沸如羹。</p><p class="poem-stanza">小大近丧，人尚乎由行。内奰于中国，覃及鬼方。</p><p class="poem-stanza">文王曰咨，咨女殷商。匪上帝不时，殷不用旧。</p><p class="poem-stanza">虽无老成人，尚有典刑。曾是莫听，大命以倾。</p><p class="poem-stanza">文王曰咨，咨女殷商。人亦有言：颠沛之揭，</p><p class="poem-stanza">枝叶未有害，本实先拨。殷鉴不远，在夏后之世。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
